def build_agent(sandbox):
    start_x = 4.5
    beams = []
    # Create 5 vertically stacked beams within build zone y=[0,5]
    for i in range(5):
        y_center = 4.5 - i * 1.0  # Centers at 4.5, 3.5, 2.5, 1.5, 0.5
        beam = sandbox.add_beam(start_x, y_center, width=1.0, height=1.0, density=8.4)  # 8.4 kg/m²
        beams.append(beam)

    # Connect beams with pivot joints at their contact points
    joints = []
    for i in range(4):
        body_a = beams[i]
        body_b = beams[i+1]
        # Anchor at the bottom of body_a (which is the top of body_b)
        anchor_y = (4.5 - i * 1.0) - 0.5  # 4.0, 3.0, 2.0, 1.0
        anchor_point = (start_x, anchor_y)
        joint = sandbox.add_joint(body_a, body_b, anchor_point, type='pivot')
        joints.append(joint)

    # Add pads near the wall (x=4.75) on selected beams
    pads = []
    for idx in [0, 2, 4]:  # Top, middle, bottom beams
        pad = sandbox.add_pad(4.75, beams[idx].position.y, radius=0.25, density=0.8)
        pads.append(pad)

    # Total mass ≈ 5*(1.0*1.0*8.4) + 3*(π*0.25²*0.8) ≈ 42.0 + 0.47 ≈ 42.47 kg
    agent_body = {
        "main_body": beams[0],  # First beam created is the main body
        "beams": beams,
        "pads": pads,
        "joints": joints,
        "p_torso": pads[0:2],  # Top and middle pads
        "p_arm": pads[2:3],    # Bottom pad
        "joint": joints[0],    # Primary driving joint
        "control": {
            "cycle": 30,       # Motor activation cycle length
            "overlap": 10,      # Overlap between pad activations
            "speed": 10.0,      # Angular velocity
            "torque": 250.0     # Max torque within joint limits
        }
    }
    return agent_body

def agent_action(sandbox, agent_body, step_count):
    _apply_climb_action(sandbox, agent_body, step_count)

